public class Assignment1_TypeCasting {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		double num1=10.75;
		int num2=((int)num1);
		
		System.out.println("Double Variable: "+num1);
		System.out.println("Integer Variable: "+num2);
			

	}

}
